import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import {fetchJson} from '../utils/fetch-json'

export type CheckForNewFixesResponse = {
  message: string
}

export function useCheckForNewFixes(path: string): UseMutationResult<CheckForNewFixesResponse> {
  return useMutation({
    mutationFn: () => {
      return fetchJson(path, {
        method: 'post',
      })
    },
  })
}
