import {DataTable, Table} from '@primer/react/experimental'
import type {Column, DataTableProps} from '@primer/react/experimental'

export interface PlatformPatternsDataTableRow {
  id: string
  name: string
  description: string
}

const defaultData: PlatformPatternsDataTableRow[] = [
  {id: '1', name: 'Item 1', description: 'Description for item 1'},
  {id: '2', name: 'Item 2', description: 'Description for item 2'},
  {id: '3', name: 'Item 3', description: 'Description for item 3'},
]

const defaultColumns: Array<Column<PlatformPatternsDataTableRow>> = [
  {
    header: 'Name',
    field: 'name',
    rowHeader: true,
  },
  {
    header: 'Description',
    field: 'description',
  },
]

const defaultDataTableProps = {}

export interface PlatformPatternsDataTableProps {
  title?: string
  data?: PlatformPatternsDataTableRow[]
  columns?: Array<Column<PlatformPatternsDataTableRow>>
  ariaLabel?: string
  dataTableProps?: Omit<DataTableProps<PlatformPatternsDataTableRow>, 'data' | 'columns' | 'aria-label'>
}

export function PlatformPatternsDataTable({
  title,
  data = defaultData,
  columns = defaultColumns,
  ariaLabel = 'Data table',
  dataTableProps = defaultDataTableProps,
}: PlatformPatternsDataTableProps) {
  return (
    <div>
      {title && <h2>{title}</h2>}
      <Table.Container>
        <DataTable aria-label={ariaLabel} data={data} columns={columns} {...dataTableProps} />
      </Table.Container>
    </div>
  )
}
