import {PlatformPatternsDataTable} from './PlatformPatternsDataTable'
import type {PlatformPatternsDataTableRow} from './PlatformPatternsDataTable'

export interface PlatformPatternsWrapperProps {
  component?: 'dataTable'
  data?: PlatformPatternsDataTableRow[]
  props?: Record<string, unknown>
}

export function PlatformPatternsWrapper({component, data, props}: PlatformPatternsWrapperProps) {
  if (component === 'dataTable') {
    return <PlatformPatternsDataTable data={data} {...props} />
  }

  return null
}
